import { useState } from 'react';
import './quiz.css';
import { data } from '../../assets/data';

const Quiz = () => {
    const [index, setIndex] = useState(0);
    const [score, setScore] = useState(0);
    const [lockAns, setLockAns] = useState(false);
    const [result, setResult] = useState(null); // stores { selected: num, correct: num }

    // Handle empty data state
    if (!data || data.length === 0) {
        return (
            <div className="container">
                <h1>No Quiz Data Available</h1>
            </div>
        );
    }

    // Handle completed state
    if (index >= data.length) {
        const resetQuiz = () => {
            setIndex(0);
            setScore(0);
            setLockAns(false);
            setResult(null);
        };

        return (
            <div className="container">
                <h1>Quiz Completed!</h1>
                <hr />
                <h2>Your Score: {score} / {data.length}</h2>
                <button onClick={resetQuiz}>Restart Quiz</button>
            </div>
        );
    }

    const { question, option1, option2, option3, option4, ans } = data[index];
    const options = [option1, option2, option3, option4];

    const handleNextClick = () => {
        if (!lockAns) {
            alert("Please select an option before proceeding.");
            return;
        }
        setIndex(prev => prev + 1);
        setLockAns(false);
        setResult(null);
    };

    const checkAns = (selectedOption) => {
        if (lockAns) return;

        setResult({
            selected: selectedOption,
            correct: ans
        });

        if (selectedOption === ans) {
            setScore(prev => prev + 1);
        }
        setLockAns(true);
    };

    const getOptionClass = (optionNum) => {
        if (!result) return "";
        if (optionNum === result.correct) return "correct";
        if (optionNum === result.selected && result.selected !== result.correct) return "wrong";
        return "";
    };

    return (
        <div className='container'>
            <h1>Quiz App</h1>
            <hr />
            <h2>Question {index + 1}: {question}</h2>
            <ul>
                {options.map((opt, i) => {
                    const optionNum = i + 1;
                    return (
                        <li 
                            key={optionNum}
                            className={getOptionClass(optionNum)}
                            onClick={() => checkAns(optionNum)}
                        >
                            {opt}
                        </li>
                    );
                })}
            </ul>
            <button onClick={handleNextClick}>
                {index < data.length - 1 ? 'Next' : 'Submit'}
            </button>
            <div className='index'>{index + 1} of {data.length}</div>
        </div>
    );
};

export default Quiz;
```

